  // export / import / help / search
  'ex.title': ['Sichern & Export', 'Save & export'], 'ex.n': ['{0} Entscheidungen. Prüfer: {1}', '{0} decisions. Reviewer: {1}'], 'ex.h1': ['1. Sicherung', '1. Backup'], 'ex.p1': ['Entscheidungen liegen im Browser. Eine Sicherungsdatei schützt vor Verlust.', 'Decisions live in the browser. A backup file protects against loss.'],
